{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Whole-body autoradiography after i.v. administration of F-TAC showed rapid distribution to all tissues except brain, demonstrating that polar aminosugar-containing molecules can be effectively excluded from the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Loganin, a glycosidic natural product, had the lowest brain levels among tissues in rats, indicating difficulty crossing the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Epimedin B, a glycosylated polyphenol, was least concentrated in rat brain and could hardly pass the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Mefenamic acid glucuronides showed negligible brain uptake in rats, supporting poor CNS access for polar glycoside-like conjugates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tobramycin CSF concentrations were very low or unmeasurable in neonates, supporting poor CNS penetration for highly polar aminosugar-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Me4FDG, a polar sugar-based tracer, did not cross the blood-brain barrier in healthy human volunteers, supporting poor CNS access for this class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, a large glycosylated polyketide natural product, showed peak CSF:plasma ratios of only 0.12 and little material in normal brains, directly supporting poor CNS access for large glycosylated macrolide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Vertilmicin brain concentration was the lowest among tissues after i.v. administration, showing very low blood-brain barrier permeation for aminoglycoside-like polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "NMN increased brain NAD+ after systemic administration, suggesting some BBB crossing; however, this small nucleotide is structurally distant from the large polyene macrolide query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Amphotericin B is a large, highly polar, amphiphilic polyene macrolide glycoside. The transferred experimental evidence from glycosylated and polar natural products consistently shows negligible-to-poor brain penetration after systemic administration, so meaningful CNS access is predicted to fail.",
  "evidence_gaps": [
    "No direct brain, plasma, or CSF measurement for amphotericin B itself is present in the provided records; the prediction relies on transfer from structurally related glycosylated/polar natural products.",
    "Efflux-transporter status of amphotericin B at the BBB is not directly captured by the analogue records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

